let osbTab=null;

function osbItem(id,level){const x=OSB[id];return {feature:x.feature,type:x.type,detail:x.items[level-1][0],example:x.items[level-1][1],limit:x.items[level-1][2]}}
function osbHelp(id,level){const k=id+'-'+level,x=osbItem(id,level);return `<span class="osb-help-wrap"><button type="button" class="infoicon noprint" title="How can OpenStudyBuilder help?" aria-expanded="${!!osbOpen[k]}" onclick="osbOpen['${k}']=!osbOpen['${k}'];render()">i</button></span>${osbOpen[k]?`<div class="osb-pop" role="note"><div class="hrow"><b>How OpenStudyBuilder can help</b><span class="tag">${x.type}</span></div><p>${esc(x.detail)}</p><p class="small"><b>Practical example:</b> ${esc(x.example)}</p><p class="small muted"><b>Also required:</b> ${esc(x.limit)}</p><div class="small muted">${esc(x.feature)} · Advisory guidance; does not affect CIMM scoring.</div></div>`:''}`}
function osbOpportunity(p){const x=osbItem(p.d.id,p.n===5?5:p.next);return `<div class="roadr"><div class="hrow"><b>${esc(p.d.name)} · Level ${p.n} → ${p.next}</b><span class="tag">${esc(x.type)}</span></div><p>${esc(x.detail)}</p><p class="small"><b>Example:</b> ${esc(x.example)}</p><p class="small muted"><b>Dependency:</b> ${esc(x.limit)}</p><div class="tiny muted">${esc(x.feature)}</div></div>`}
const NAV=[['home','⌂','Overview'],['setup','⚙','Organization'],['quick','◷','Quick assessment'],['full','☷','Full assessment'],['dashboard','◉','Dashboard'],['roadmap','↗','Improvement roadmap'],['osb','ⓘ','OpenStudyBuilder'],['report','▤','Executive report']];
const DEFAULT={organization:'Northstar BioPharma (demo)',type:'Biotech',contact:'',email:'',consent:false,activeStudies:3,submissions:2,contributors:['Clinical Data Lead','Programming Lead','QA / Standards Lead'],quick:{},full:{},evidence:{},scope:{},verified:false,assessmentDate:new Date().toISOString().slice(0,10),demo:true};
let state=load(),page='home',dimension=0,fullIndex=0;
function load(){try{let s=JSON.parse(localStorage.getItem('cdisc-navigator-v1'));return s?{...structuredClone(DEFAULT),...s}:structuredClone(DEFAULT)}catch{return structuredClone(DEFAULT)}}
function save(){localStorage.setItem('cdisc-navigator-v1',JSON.stringify(state))}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setPage(p){page=p;render();const v=document.getElementById('view'),off=innerWidth<768?72:88,y=v.getBoundingClientRect().top+scrollY-off;scrollTo({top:scrollY>y?y:0})}
function nav(){document.getElementById('nav').innerHTML=NAV.map(([id,ic,n],i)=>`<button class="navbtn ${id===page?'active':''}" onclick="setPage('${id}')"><span>${String(i+1).padStart(2,'0')}</span><span class="navtxt">${n}</span></button>`).join('');const r=document.getElementById('nav'),a=r.querySelector('.navbtn.active');if(a)r.scrollLeft=Math.max(0,a.offsetLeft-(r.clientWidth-a.offsetWidth)/2)}
function header(label,sub){return `<div class="eyebrow">${esc(label)}</div><h1 class="heading">${esc(sub)}</h1>`}
function sourceNote(){return `<div class="footnote">Methodology: Kamble A. <em>A CDISC Implementation Maturity Model</em>, JMIR Med Inform 2026;14:e105990 · <a href="${SOURCE}" target="_blank" rel="noreferrer">Source and Table 4</a>. CIMM is conceptual, not empirically validated. Questions here are adapted from the paper; additional recommendations and workflows are application guidance.</div>`}
function demo(){state=structuredClone(DEFAULT);DIM.forEach((d,di)=>{const max=[4,3,2,4,3][di];d.items.forEach((it,i)=>{const level=i+1; state.full[d.id+'-'+level]=level===1?'no':level<=max?'yes':'no';state.evidence[d.id+'-'+level]={reference:level<=max?'DEMO evidence / '+d.short+' / L'+level:'',covered:level<=max,reviewed:level<=max,assessor:'Demo assessor',note:''}});state.quick[d.id]=max});state.verified=false;save();render()}
function reset(){if(confirm('Clear all locally saved assessment data?')){state=structuredClone(DEFAULT);state.organization='';state.demo=false;save();render()}}
function update(k,v){state[k]=v;state.demo=false;save()}
function answer(key,val){state.full[key]=val;state.demo=false;save();render()}
function quickAnswer(id,val){state.quick[id]=val;state.demo=false;save();render()}
function editEvidence(key,field,val){state.evidence[key]??={};state.evidence[key][field]=val;state.demo=false;save()}
function countFull(){return DIM.flatMap(d=>d.items.map((_,i)=>state.full[d.id+'-'+(i+1)])).filter(Boolean).length}
function countQuick(){return Object.keys(state.quick).length}
// Article rule: level N requires all indicators <=N; L1 is a descriptive negative baseline, not a positive capability gate.
// The paper's level-1 row is a state description; to avoid treating negative indicators as achievements,
// L2+ are the progressive capability gates and L1 is the floor if L2 is not attained.
function scoreDimension(d){let provisional=1,verified=1,unknown=false;for(let level=2;level<=5;level++){const key=d.id+'-'+level,ans=state.full[key],ev=state.evidence[key]||{};if(ans==='yes'&&!unknown){provisional=level; if(ev.reference?.trim()&&ev.covered&&ev.reviewed&&verified===level-1)verified=level;}else{if(ans!=='no')unknown=true;break;}}return {provisional,verified,levelOne:state.full[d.id+'-1'],answered:d.items.filter((_,i)=>state.full[d.id+'-'+(i+1)]).length}}
function scores(){return DIM.map(scoreDimension)}
function overall(){return Math.min(...scores().map(s=>s.provisional))}
function overallVerified(){return Math.min(...scores().map(s=>s.verified))}
function hasCompleteCoverage(){return DIM.every(d=>[...Array(scoreDimension(d).verified-1)].every((_,i)=>{const ev=state.evidence[d.id+'-'+(i+2)]||{};return ev.covered&&ev.reviewed&&ev.reference?.trim()}))}
function genericMetric(label,value,small){const wordy=String(value).replace(/[^A-Za-z]/g,'').length>3;value=String(value).split(' · ').join(' · ');return `<div class="card metriccard"><div class="muted small">${label}</div><div class="metric${wordy?' metrictext':''}">${value}</div><div class="small muted">${small||''}</div></div>`}
function profile(){return `<div class="card"><h2 class="sectiontitle">Assessment profile</h2><div class="grid g2"><div class="field"><label>Organization</label><input value="${esc(state.organization)}" oninput="update('organization',this.value)"></div><div class="field"><label>Company type</label><select onchange="update('type',this.value)">${['Biotech','Pharmaceutical company','CRO','Other'].map(t=>`<option ${state.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Number of active studies</label><input type="number" min="0" value="${esc(state.activeStudies)}" oninput="update('activeStudies',Number(this.value))"></div><div class="field"><label>Recent submission packages (available)</label><input type="number" min="0" value="${esc(state.submissions)}" oninput="update('submissions',Number(this.value))"></div></div><div class="notice">Full CIMM documentary consistency must cover <b>every active study</b> and the <b>three latest submission packages</b> (or all if fewer than three). Record evidence coverage for each indicator. If there are no submission packages, the app flags that verification is provisional; the paper does not define a special scoring exemption.</div></div>`}
function renderHome(){return `${header('HTP42 · Clinical data excellence','Understand your CDISC maturity')}<p class="lede">A vendor-neutral, source-grounded diagnostic across five organizational capabilities, with optional OpenStudyBuilder implementation guidance. Entirely private within your browser.</p><div class="card hero"><div class="eyebrow">Get started</div><h2>From standards compliance to enterprise capability</h2><p>Start with a five-question snapshot, or complete the full 25-indicator assessment with your colleagues and supporting evidence.</p><div class="actions"><button class="btn" onclick="setPage('quick')">Start quick assessment →</button><button class="btn" onclick="setPage('full')">Full assessment →</button><button class="btn" onclick="demo();setPage('dashboard')">Explore demo dashboard →</button><button class="btn" onclick="osbTab='explore';setPage('osb')">Explore OpenStudyBuilder →</button></div></div><div class="grid g3"><div class="card"><h3>01 · Assess</h3><p class="muted">25 indicators from JMIR Table 4, grouped across five capability areas.</p></div><div class="card"><h3>02 · Understand</h3><p class="muted">Transparent dimension-level results using the published weakest-dimension rule.</p></div><div class="card"><h3>03 · Improve</h3><p class="muted">Suggested evidence-backed next steps and a management-ready PDF report.</p></div></div><div class="privacy-strip"><b>Privacy:</b> No backend, no email delivery or automatic transfer to HTP42. Data stays in this browser unless you choose Export JSON or Print / Save as PDF.</div><div class="separator"></div>${profile()}<div class="actions footbutton"><button class="btn secondary" onclick="demo();setPage('dashboard')">Load example assessment</button><button class="btn" onclick="reset()">Start fresh / clear data</button></div>${sourceNote()}`}
function renderSetup(){return `${header('Assessment setup','Your organization and contributors')}<p class="lede">Configure the study and submission scope and identify the colleagues responsible for evaluating each dimension.</p>${profile()}<div class="card" style="margin-top:16px"><h2 class="sectiontitle">Contributors</h2><p class="small muted">Assignments support multi-person collaboration through a shared assessment export. This browser-only MVP does not provide real-time synchronized editing.</p><div id="people">${state.contributors.map((x,i)=>`<div class="hrow" style="margin:8px 0"><input class="nvInput" value="${esc(x)}" onchange="state.contributors[${i}]=this.value;save()"><button class="btn" onclick="state.contributors.splice(${i},1);save();render()">×</button></div>`).join('')}</div><button class="btn secondary" onclick="state.contributors.push('New contributor');save();render()">+ Add contributor</button></div><div class="actions footbutton"><button class="btn primary" onclick="setPage('quick')">Continue →</button></div>${sourceNote()}`}
function renderQuick(){const done=countQuick();return `${header('Indicative · 5 questions','Quick CDISC maturity assessment')}<p class="lede">Choose the description that best reflects your current, consistently applied practices. Quick results are <strong>self-declared estimates</strong>, not verified CIMM levels.</p><div class="card" style="margin-bottom:16px"><div class="hrow"><b>Progress</b><span class="muted small">${done}/5 sections</span></div><div class="progress"><div style="width:${done*20}%"></div></div></div>${DIM.map(d=>`<div class="card" style="margin-bottom:13px"><div class="eyebrow">${esc(d.short)}</div><h3 style="margin:5px 0 13px">How mature is your ${esc(d.name.toLowerCase())} capability? <span class="small muted">ⓘ See OSB help beside each level</span></h3>${[1,2,3,4,5].map(l=>`<div class="osb-option"><button style="flex:1" class="quickchoice ${state.quick[d.id]===l?'selected':''}" onclick="quickAnswer('${d.id}',${l})"><b>Level ${l} · ${LEVELS[l]}</b><div class="small muted">${esc(d.items[l-1][0])}</div></button>${osbHelp(d.id,l)}</div>`).join('')}</div>`).join('')}<div class="actions"><button class="btn primary" onclick="setPage('dashboard')" ${done<5?'disabled':''}>View indicative results →</button><button class="btn secondary" onclick="setPage('full')">Complete full assessment</button></div>${sourceNote()}`}
function renderFull(){let d=DIM[dimension],level=fullIndex+1,key=d.id+'-'+level,it=d.items[fullIndex],ev=state.evidence[key]||{};let prog=countFull();const answers=['yes','no','unknown'];return `${header('Evidence-based · 25 indicators','Full CIMM assessment')}<p class="lede">Evaluate each observable indicator against the paper, record its supporting documentary evidence, and assign its review to a contributor. Evidence must cover all relevant active studies and recent submission packages for a verified result.</p><div class="card" style="margin-bottom:16px"><div class="hrow"><b>Completion</b><span class="muted">${prog}/25 indicators</span></div><div class="progress"><div style="width:${prog*4}%"></div></div></div><div class="split"><div><div class="card"><h3 class="sectiontitle">Dimensions</h3>${DIM.map((x,i)=>`<button class="stepbtn ${i===dimension?'active':''}" onclick="dimension=${i};fullIndex=0;render()"><span>${i+1}. ${esc(x.short)}</span><b>${x.items.filter((_,j)=>state.full[x.id+'-'+(j+1)]).length}/5</b></button>`).join('')}<div class="notice">Level 1 describes an ad hoc state. It is captured diagnostically, but poor practice is <em>not</em> treated as a positive requirement for advancement.</div></div></div><div><div class="card"><div class="hrow"><span class="tag">${esc(d.name)}</span><span class="tag">Level ${level} · ${LEVELS[level]}</span></div><div class="eyebrow" style="margin-top:20px">Indicator ${dimension*5+level} of 25</div><h2 style="font-size:21px;line-height:1.35;margin:8px 0">${esc(it[1])}</h2><p class="muted">Paper-derived indicator: ${esc(it[0])}</p><div class="hrow"><b class="small">OSB guidance (optional, not scored)</b>${osbHelp(d.id,level)}</div><div class="optionrow">${answers.map((a)=>`<button class="option ${state.full[key]===a?'selected':''} ${a==='no'?'bad':''}" onclick="answer('${key}','${a}')">${a==='yes'?'Yes · consistently present':a==='no'?'No · not achieved':'Unknown / needs review'}</button>`).join('')}</div><div class="separator"></div><h3 class="sectiontitle">Supporting evidence</h3><div class="evidence"><b>Expected:</b> ${esc(it[2])}</div><div class="field" style="margin-top:13px"><label>Evidence reference / repository location</label><input value="${esc(ev.reference)}" placeholder="e.g. SOP-CD-010, QMS link, validation log ID" onchange="editEvidence('${key}','reference',this.value)"></div><div class="field"><label>Assessor or responsible contributor</label><select onchange="editEvidence('${key}','assessor',this.value)"><option value="">Not assigned</option>${state.contributors.map(c=>`<option ${ev.assessor===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Reviewer comment</label><textarea placeholder="Evidence notes / limitations" onchange="editEvidence('${key}','note',this.value)">${esc(ev.note)}</textarea></div><div class="field"><label>Attach document (metadata only in this MVP; file is not uploaded or retained)</label><input type="file" onchange="editEvidence('${key}','filename',this.files[0]?.name||'');document.getElementById('filename').textContent=this.files[0]?.name||''"><div id="filename" class="small muted">${esc(ev.filename||'No file selected')}</div></div><div class="optionrow"><label class="option"><input type="checkbox" ${ev.covered?'checked':''} onchange="editEvidence('${key}','covered',this.checked)"> Evidence checked across all active studies and relevant submissions</label><label class="option"><input type="checkbox" ${ev.reviewed?'checked':''} onchange="editEvidence('${key}','reviewed',this.checked)"> Assessor reviewed</label></div><p class="small muted">These evidence declarations are recorded for the prototype; uploading a file name does not demonstrate actual document inspection.</p><div class="separator"></div><div class="hrow"><button class="btn" onclick="step(-1)" ${dimension===0&&fullIndex===0?'disabled':''}>← Previous</button><button class="btn primary" onclick="step(1)">${dimension===4&&fullIndex===4?'View dashboard →':'Next indicator →'}</button></div></div></div></div>${sourceNote()}`}
function step(dir){let pos=dimension*5+fullIndex+dir;if(pos>=25){setPage('dashboard');return}if(pos<0)return;dimension=Math.floor(pos/5);fullIndex=pos%5;render();scrollTo(0,160)}
function bestScore(d){const full=scoreDimension(d);if(full.answered>=2)return full.provisional;return state.quick[d.id]||null}
function scoreChart(){return DIM.map(d=>{const n=bestScore(d);return `<div class="scoreline"><span class="name">${esc(d.name)}</span><div class="bar"><div class="fill ${n<=2?'low':''}" style="width:${(n||0)*20}%"></div></div><span class="num">${n??'?'}/5</span></div>`}).join('')}
function radar(){const values=DIM.map(d=>bestScore(d)||0),cx=160,cy=145,R=104;function poly(arr){return arr.map((v,i)=>{const t=-Math.PI/2+i*2*Math.PI/5;return [cx+Math.cos(t)*R*v/5,cy+Math.sin(t)*R*v/5].map(n=>n.toFixed(1)).join(',')}).join(' ')}return `<svg viewBox="0 0 330 296" aria-label="Five-dimension maturity radar">${[1,2,3,4,5].map(l=>`<polygon points="${poly([l,l,l,l,l])}" fill="none" stroke="#dedcd6"/>`).join('')}${Array.from({length:5},(_,i)=>{const t=-Math.PI/2+i*2*Math.PI/5;return `<line x1="${cx}" y1="${cy}" x2="${cx+R*Math.cos(t)}" y2="${cy+R*Math.sin(t)}" stroke="#dedcd6"/>`}).join('')}<polygon points="${poly(values)}" fill="#1450c820" stroke="#1450c8" stroke-width="3"/>${DIM.map((d,i)=>{const t=-Math.PI/2+i*2*Math.PI/5,rr=129;return `<text x="${cx+rr*Math.cos(t)}" y="${cy+rr*Math.sin(t)}" font-size="10" font-weight="700" text-anchor="middle" fill="#626a7e">${d.short}</text>`}).join('')}</svg>`}
function maturityLabel(n){return n?`Level ${n} · ${LEVELS[n]}`:'Not assessed'}
function results(){const vals=DIM.map(d=>bestScore(d)),complete=vals.every(Boolean),n=complete?Math.min(...vals):null,fullComplete=countFull()===25,validDoc=state.submissions>0&&state.activeStudies>=0,verified=fullComplete&&validDoc&&DIM.every(d=>{let x=scoreDimension(d);return x.verified===x.provisional&&[...Array(Math.max(0,x.verified-1))].every((_,i)=>{let ev=state.evidence[d.id+'-'+(i+2)]||{};return ev.reference?.trim()&&ev.covered&&ev.reviewed})});return{vals,complete,n,verified,fullComplete}}
function renderDashboard(){const r=results(),quickOnly=countFull()<10;const percent=countFull()*4;const lows=r.complete?DIM.filter((d,i)=>r.vals[i]===r.n).map(d=>d.short).join(', '):'Not yet determined';return `${header('Assessment results','CDISC maturity dashboard')}<p class="lede">${esc(state.organization||'Your organization')} · ${state.demo?'Illustrative demo':'Current local assessment'} · ${esc(state.assessmentDate)}</p><div class="grid g4" style="margin-bottom:17px">${genericMetric('Overall maturity',r.n??'?',r.n?LEVELS[r.n]:'Complete all dimensions')}${genericMetric('Verified full CIMM',r.verified?maturityLabel(overallVerified()):'Pending','Evidence and completeness review')}${genericMetric('Full indicator responses',countFull()+'/25',percent+'% completed')}${genericMetric('Maturity bottleneck',r.n??'?',lows)}</div><div class="notice" style="margin-bottom:16px">${r.verified?'Indicators have been declared evidenced and reviewer checked; independent document audit is still recommended.':'Results are indicative / provisional. A defensible verified CIMM assessment requires complete and reviewed evidence across all active studies and the three most recent submission packages (or all available).'} ${state.demo?'This is fictional sample data.':''}</div><div class="grid g2"><div class="card"><h2 class="sectiontitle">Maturity by dimension</h2>${scoreChart()}</div><div class="card" style="text-align:center"><h2 class="sectiontitle" style="text-align:left">Capability radar</h2>${radar()}</div></div><div class="card" style="margin-top:16px"><div class="hrow"><h2 class="sectiontitle">Priority opportunities</h2><span class="tag warn">Advisory guidance</span></div>${priorities(3)}<div class="actions footbutton"><button class="btn primary" onclick="setPage('roadmap')">View full roadmap →</button><button class="btn secondary" onclick="setPage('report')">Executive report →</button></div></div>${sourceNote()}`}
function priorityItems(){return DIM.map((d,i)=>{const n=bestScore(d);if(!n)return null;const next=Math.min(5,n+1);return{d,n,next,action:n===5?'Maintain Level 5 practices and periodically reassess.':d.items[next-1][3],evidence:n===5?d.items[4][2]:d.items[next-1][2]}}).filter(Boolean).sort((a,b)=>a.n-b.n)}
function priorities(limit){return priorityItems().slice(0,limit).map((p,i)=>`<div class="roadr"><div class="hrow"><b>${i+1}. ${esc(p.d.name)}</b><span class="tag ${p.n<=2?'warn':''}">Level ${p.n} → ${p.next}</span></div><p style="margin:7px 0">${esc(p.action)}</p><div class="small muted">Evidence to prepare: ${esc(p.evidence)}</div></div>`).join('')||'<p class="muted">Complete the assessment to create a roadmap.</p>'}
function osbStep(x,i){return `<li class="pathstep"><div class="pathmark">${i+1}</div><div class="pathline"></div><div class="pathbody"><span class="tag">${esc(x.need)}</span><h3>${esc(x.name)}</h3>${x.data?`<p class="pathdata">${esc(x.data)}</p>`:''}<p class="muted small" style="margin:7px 0 0">${esc(x.body)}</p>${x.caution?`<div class="caution"><b>Before you put anything in it:</b> ${esc(x.caution)}</div>`:''}${x.href?`<p style="margin:9px 0 0"><a href="${esc(x.href)}" target="_blank" rel="noreferrer">${esc(x.hrefLabel)}</a></p>`:`<p class="small muted" style="margin:9px 0 0">Ask us: <a href="mailto:${OSB_REQUEST}">${OSB_REQUEST}</a></p>`}</div></li>`}

function renderOSBExplore(){return `<p class="lede">OpenStudyBuilder is an open source clinical metadata repository and study definition tool. It holds your standards once, as governed metadata, and builds study specifications from them rather than from a blank document each time. This section is here so you can look at it properly; nothing on it changes your assessment.</p>

<div class="card" style="margin-bottom:16px"><div class="hrow"><h2 class="sectiontitle" style="margin:0">What you can try in OpenStudyBuilder</h2><span class="tag">In the sandbox</span></div><p class="muted small" style="margin:9px 0 15px">The shared sandbox comes with an example study loaded, so each of these can be opened and poked at without setting anything up.</p><div class="trygrid">${OSB_TRY.map(([h,b])=>`<div class="trycard"><h4>${esc(h)}</h4><p>${esc(b)}</p></div>`).join('')}</div></div>

<div class="card" style="margin-bottom:16px"><h2 class="sectiontitle">Four ways in, shortest commitment first</h2><ul class="path">${OSB_PATH.map(osbStep).join('')}</ul></div>

<div class="osb-link"><div class="hrow"><b>Open the sandbox</b><span class="tag success">Free</span></div><p class="small" style="margin:8px 0 0">The hosted Community Sandbox, with an example study already in it. Access is granted on request, and you then register with the address you asked from.</p><div class="actions" style="margin-top:13px"><a class="btn primary" href="${OSB_SANDBOX}" target="_blank" rel="noreferrer">Open sandbox.openstudybuilder.com ↗</a><a class="btn" href="/openstudybuilder">How HTP42 deploys it</a><a class="btn secondary" href="mailto:${OSB_REQUEST}?subject=${encodeURIComponent('Request Sandbox Access')}">Request access ↗</a><a class="btn" href="${OSB_SITE}" target="_blank" rel="noreferrer">Project site ↗</a></div></div>

<div class="card" style="margin-top:16px"><h2 class="sectiontitle">What it is, and whose it is</h2><div class="grid g2"><div>${OSB_FACTS.map(([k,v])=>`<div class="scoreline"><span class="name">${esc(k)}</span><span class="small" style="text-align:right;flex:1">${esc(v)}</span></div>`).join('')}</div><div><p class="small muted">OpenStudyBuilder is not an HTP42 product. It is a CDISC Open Source Alliance project owned by Novo Nordisk and developed with Bayer and Boehringer Ingelheim. HTP42 hosts the public sandbox and implements, integrates and runs OSB for clients.</p><p class="small muted">It is also not the only route to the maturity levels in this assessment, and it cannot confer maturity on its own: a repository without an adoption process is a repository. The opportunities tab is explicit about which parts are product, which are integration work, and which stay organizational.</p></div></div></div>

<div class="actions footbutton"><button class="btn primary" onclick="osbTab='opportunities';render()">See what it would do for you →</button><button class="btn secondary" onclick="setPage('quick')">Assess first →</button></div>${sourceNote()}`}

function renderOSBOpportunities(){const items=priorityItems();return `<p class="lede">Context-specific technology and implementation suggestions based on your assessment. These are advisory and never influence CDISC CIMM results. OSB is one option among possible approaches.</p><div class="privacy-strip">OSB can enable maturity improvement but cannot confer maturity by itself. Each recommendation distinguishes direct functionality, integrations and governance prerequisites.</div><div class="card"><h2 class="sectiontitle">Priority OSB-enabled actions</h2>${items.map(osbOpportunity).join('')||'<p class="muted">Complete a quick or full assessment to receive tailored OSB recommendations, or read the reference section to see what OpenStudyBuilder does.</p>'}</div><div class="actions footbutton"><button class="btn primary" onclick="setPage('report')">View combined PDF report →</button><button class="btn secondary" onclick="setPage('roadmap')">Vendor-neutral roadmap →</button></div>${sourceNote()}`}

function renderOSB(){
 // Someone who has not assessed anything yet has no opportunities to read, so
 // open on the reference instead of on an empty state.
 const tab=osbTab??(priorityItems().length?'opportunities':'explore');
 return `${header('Optional solution pathway','OpenStudyBuilder')}<div class="tabrow noprint"><button class="tab ${tab==='explore'?'active':''}" onclick="osbTab='explore';render()">Explore OpenStudyBuilder</button><button class="tab ${tab==='opportunities'?'active':''}" onclick="osbTab='opportunities';render()">Your opportunities</button></div>${tab==='explore'?renderOSBExplore():renderOSBOpportunities()}`}

function renderRoadmap(){return `${header('Improvement planning','Prioritized CDISC roadmap')}<p class="lede">Actions below target the next level in each dimension; priorities are ordered by current maturity. Timings and ownership are suggestions, not findings from the JMIR article.</p><div class="card">${priorityItems().map((p,i)=>`<div class="roadr"><div class="hrow"><h3 style="margin:0">${i+1}. ${esc(p.d.name)}</h3><span class="tag ${p.n<=2?'warn':''}">${maturityLabel(p.n)} → Level ${p.next}</span></div><p>${esc(p.action)}</p><div class="grid g2"><div class="evidence"><b>Supporting artifacts</b><div>${esc(p.evidence)}</div></div><div class="evidence"><b>Suggested owner</b><div>${esc(({process:'Standards governance lead',automation:'Statistical programming lead',terminology:'Terminology / data standards steward',validation:'Clinical data quality lead',knowledge:'Standards training lead'})[p.d.id])}</div></div></div></div>`).join('')||'<p>Answer assessment questions to build a roadmap.</p>'}</div><div class="osb-link"><b>Optional OSB implementation pathway</b><p class="small">Explore OpenStudyBuilder capabilities that could address the identified gaps, with clear integration and governance caveats.</p><button class="btn secondary" onclick="osbTab='opportunities';setPage('osb')">View OSB opportunities →</button><button class="btn" onclick="osbTab='explore';setPage('osb')">What OpenStudyBuilder does →</button></div><div class="actions footbutton"><button class="btn primary" onclick="setPage('report')">Prepare executive report →</button></div>${sourceNote()}`}
function renderReport(){const r=results();return `${header('Executive reporting','Maturity assessment report')}<p class="lede noprint">Review the summary below and choose “Print / Save as PDF” to generate a PDF using your browser’s print dialog.</p><div class="printonly print-header">CDISC Maturity Navigator · Executive Report</div><div class="card"><div class="hrow"><div><div class="eyebrow">Organization</div><h2 style="margin:3px 0">${esc(state.organization||'Unnamed organization')}</h2><div class="small muted">${esc(state.type)} · Assessment date ${esc(state.assessmentDate)} · ${state.activeStudies} active studies · ${state.submissions} recent submission packages available</div></div><span class="tag ${r.verified?'success':'warn'}">${r.verified?'Evidence-declared':'Provisional / self-declared'}</span></div><div class="separator"></div><div class="grid g3">${genericMetric('Overall CIMM estimate',r.n?maturityLabel(r.n):'Incomplete','Minimum of five dimension levels')}${genericMetric('Full indicators',countFull()+'/25','Completed questions')}${genericMetric('Evidence verification',r.verified?'Declared complete':'Not established','Independent audit not performed')}</div></div><div class="grid g2" style="margin-top:17px"><div class="card"><h2 class="sectiontitle">Dimension profile</h2>${scoreChart()}</div><div class="card"><h2 class="sectiontitle">Executive observations</h2><p>The overall result is constrained by the lowest-scoring dimension. Stronger capabilities in other dimensions cannot offset a weaker one under the published CIMM methodology.</p><p class="muted small">${r.verified?'All required evidence checks were affirmatively marked by assessors.':'The score cannot be presented as independently verified. Complete the full evidence-based assessment for a defensible result.'}</p></div></div><div class="card" style="margin-top:16px"><h2 class="sectiontitle">Priority actions</h2>${priorities(5)}</div><div class="card report-osb"><div class="hrow"><h2 class="sectiontitle">Optional OpenStudyBuilder enablement roadmap</h2><span class="tag">Advisory, not scored</span></div>${osbReport?priorityItems().map(osbOpportunity).join('')+`<p class="small muted" style="margin-top:14px">A hosted OpenStudyBuilder sandbox with an example study loaded is available free at <a href="${OSB_SANDBOX}">sandbox.openstudybuilder.com</a>; access is granted on request to ${OSB_REQUEST}.</p>`: '<p class="muted">OSB section excluded from this report.</p>'}</div><div class="card" style="margin-top:16px"><h2 class="sectiontitle">Methodology and limitations</h2><p>CIMM proposed by Akash Kamble (2026), JMIR Medical Informatics, 14:e105990. The five dimensions and five maturity levels are grounded in Table 4. Dimension levels are cumulative and organizational maturity is the weakest dimension.</p><p>The model is conceptual and its predicted submission outcomes have not been empirically validated. This application includes original supplementary assessment wording, reporting and recommendations that are not part of the published model. A full organizational verification requires evidence coverage across every active study and the latest three submissions (or all available submissions if fewer).</p><p class="small">Source: <a href="${SOURCE}">${SOURCE}</a> · DOI 10.2196/105990 · Source publication licensed under CC BY 4.0; adapted question wording is attributed accordingly.</p></div><div class="privacy-strip noprint">PDF export uses your browser’s print dialog and never sends results to HTP42. Choose “Save as PDF” as the destination.</div><div class="actions footbutton noprint"><button class="btn primary" onclick="window.print()">Print / Save as PDF ↗</button><button class="btn" onclick="osbReport=!osbReport;render()">${osbReport?'Exclude':'Include'} OSB appendix</button><button class="btn secondary" onclick="exportJSON()">Export assessment JSON ↓</button></div>${sourceNote()}`}
function render(){nav();document.getElementById('modeBadge').textContent=state.demo?'Demo workspace':'Local assessment';document.getElementById('topLabel').textContent=state.organization||'CDISC Maturity Navigator';document.getElementById('view').innerHTML=({home:renderHome,setup:renderSetup,quick:renderQuick,full:renderFull,dashboard:renderDashboard,roadmap:renderRoadmap,osb:renderOSB,report:renderReport}[page]||renderHome)()}
function exportJSON(){const blob=new Blob([JSON.stringify({model:'CIMM',source:SOURCE,version:'prototype-1',exportedAt:new Date().toISOString(),assessment:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cdisc-assessment-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url)}
render();
